namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeData
{
    public static List<Recipe> Recipes { get; } = new()
    {
        new Recipe
        {
            Id = 1, Title = "Bruschetta", Category = "appetizers",
            Ingredients = "Baguette, tomatoes, garlic, basil, olive oil, salt, pepper",
            Steps = "1. Slice and toast the baguette.\n2. Dice tomatoes and mix with minced garlic, basil, olive oil, salt, and pepper.\n3. Spoon the tomato mixture onto the toasted bread.\n4. Serve immediately.",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Stuffed Mushrooms", Category = "appetizers",
            Ingredients = "Button mushrooms, cream cheese, garlic, parmesan, breadcrumbs, parsley",
            Steps = "1. Remove stems from mushrooms.\n2. Mix cream cheese, garlic, parmesan, and breadcrumbs.\n3. Fill mushroom caps with the mixture.\n4. Bake at 375°F for 20 minutes.",
            AverageRating = 4.2, RatingCount = 8
        },
        new Recipe
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "main-courses",
            Ingredients = "Spaghetti, eggs, pecorino romano, guanciale, black pepper",
            Steps = "1. Cook spaghetti in salted water.\n2. Crisp the guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale, then stir in egg mixture off heat.\n5. Serve with extra cheese and pepper.",
            AverageRating = 4.8, RatingCount = 25
        },
        new Recipe
        {
            Id = 4, Title = "Chicken Tikka Masala", Category = "main-courses",
            Ingredients = "Chicken thighs, yogurt, garam masala, tomato sauce, cream, onion, garlic, ginger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil the chicken until charred.\n3. Sauté onion, garlic, and ginger, then add tomato sauce and cream.\n4. Add chicken to the sauce and simmer 10 minutes.\n5. Serve with rice or naan.",
            AverageRating = 4.7, RatingCount = 18
        },
        new Recipe
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "desserts",
            Ingredients = "Dark chocolate, butter, eggs, sugar, flour",
            Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until thick.\n3. Fold chocolate mixture into eggs, then fold in flour.\n4. Pour into greased ramekins.\n5. Bake at 425°F for 12 minutes.\n6. Invert onto plates and serve immediately.",
            AverageRating = 4.9, RatingCount = 30
        },
        new Recipe
        {
            Id = 6, Title = "Tiramisu", Category = "desserts",
            Ingredients = "Ladyfingers, mascarpone, eggs, sugar, espresso, cocoa powder, marsala wine",
            Steps = "1. Whisk egg yolks with sugar, then fold in mascarpone.\n2. Whip egg whites and fold into mascarpone mixture.\n3. Dip ladyfingers in espresso mixed with marsala.\n4. Layer soaked ladyfingers and cream in a dish.\n5. Refrigerate overnight and dust with cocoa before serving.",
            AverageRating = 4.6, RatingCount = 15
        }
    };
}

@page "/category/{CategorySlug}"
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName</h1>

    @if (Recipes.Any())
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h4 class="card-title">@recipe.Title</h4>
                            <p class="text-muted">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
    else
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
</div>

@code {
    [Parameter]
    public string CategorySlug { get; set; } = string.Empty;

    private string CategoryName => CategorySlug switch
    {
        "appetizers" => "🥗 Appetizers",
        "main-courses" => "🍝 Main Courses",
        "desserts" => "🍰 Desserts",
        _ => CategorySlug
    };

    private List<Recipe> Recipes => RecipeData.Recipes
        .Where(r => r.Category == CategorySlug)
        .ToList();
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models

<PageTitle>@(Recipe?.Title ?? "Recipe Not Found")</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@Recipe.Title</h1>

        <div class="mb-4">
            <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
        </div>

        <div class="card mb-3">
            <div class="card-header"><h4 class="mb-0">📋 Ingredients</h4></div>
            <div class="card-body">
                <ul>
                    @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                    {
                        <li>@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header"><h4 class="mb-0">👨‍🍳 Steps</h4></div>
            <div class="card-body">
                @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <p>@step</p>
                }
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe => RecipeData.Recipes.FirstOrDefault(r => r.Id == Id);
}

@using RecipeCommunity.Models

<div class="star-rating">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "selected" : "")"
              @onclick="() => SetRating(star)"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              style="cursor: pointer; font-size: 1.5rem;">
            @(star <= (HoverRating > 0 ? HoverRating : CurrentRating) ? "★" : "☆")
        </span>
    }
    @if (Submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star.selected {
        color: #ffc107;
    }
    .star-rating .star:hover {
        color: #ffc107;
    }
</style>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int CurrentRating { get; set; }
    private int HoverRating { get; set; }
    private bool Submitted { get; set; }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
        Submitted = true;

        var recipe = RecipeData.Recipes.FirstOrDefault(r => r.Id == RecipeId);
        if (recipe is not null)
        {
            var totalRating = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalRating + rating) / recipe.RatingCount;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit Your Recipe</h1>
    <p>Share your favorite recipe with the community!</p>

    @if (SubmitSuccess)
    {
        <div class="alert alert-success">
            <strong>Recipe submitted!</strong> Your recipe "@Title" has been added to the community.
            <a href="/recipe/@NewRecipeId">View your recipe</a>
        </div>
    }

    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="SelectedCategory">
                <option value="">-- Select a category --</option>
                <option value="appetizers">Appetizers</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Ingredients"
                placeholder="Enter ingredients, one per line" />
            <div class="form-text">List each ingredient on a separate line.</div>
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Steps"
                placeholder="Enter preparation steps, one per line" />
            <div class="form-text">Describe each step on a separate line.</div>
        </div>

        <button type="submit" class="btn btn-success"
                disabled="@(string.IsNullOrWhiteSpace(Title) || string.IsNullOrWhiteSpace(Ingredients) || string.IsNullOrWhiteSpace(Steps))">
            Submit Recipe
        </button>
    </EditForm>
</div>

@code {
    private string Title { get; set; } = string.Empty;
    private string SelectedCategory { get; set; } = string.Empty;
    private string Ingredients { get; set; } = string.Empty;
    private string Steps { get; set; } = string.Empty;
    private bool SubmitSuccess { get; set; }
    private int NewRecipeId { get; set; }

    private void HandleSubmit()
    {
        var newId = RecipeData.Recipes.Max(r => r.Id) + 1;
        var recipe = new Recipe
        {
            Id = newId,
            Title = Title,
            Category = string.IsNullOrEmpty(SelectedCategory) ? "main-courses" : SelectedCategory,
            Ingredients = Ingredients.Replace("\n", ", "),
            Steps = Steps,
            AverageRating = 0,
            RatingCount = 0
        };

        RecipeData.Recipes.Add(recipe);
        NewRecipeId = newId;
        SubmitSuccess = true;

        Title = string.Empty;
        SelectedCategory = string.Empty;
        Ingredients = string.Empty;
        Steps = string.Empty;
    }
}

