namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeData
{
    public static List<Recipe> Recipes { get; } = new()
    {
        new Recipe
        {
            Id = 1, Title = "Bruschetta", Category = "appetizers",
            Ingredients = "Baguette, tomatoes, garlic, basil, olive oil, salt, pepper",
            Steps = "1. Slice and toast the baguette.\n2. Dice tomatoes and mix with minced garlic, basil, olive oil, salt, and pepper.\n3. Spoon the tomato mixture onto the toasted bread.\n4. Serve immediately.",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Stuffed Mushrooms", Category = "appetizers",
            Ingredients = "Button mushrooms, cream cheese, garlic, parmesan, breadcrumbs, parsley",
            Steps = "1. Remove stems from mushrooms.\n2. Mix cream cheese, garlic, parmesan, and breadcrumbs.\n3. Fill mushroom caps with the mixture.\n4. Bake at 375°F for 20 minutes.",
            AverageRating = 4.2, RatingCount = 8
        },
        new Recipe
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "main-courses",
            Ingredients = "Spaghetti, eggs, pecorino romano, guanciale, black pepper",
            Steps = "1. Cook spaghetti in salted water.\n2. Crisp the guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale, then stir in egg mixture off heat.\n5. Serve with extra cheese and pepper.",
            AverageRating = 4.8, RatingCount = 25
        },
        new Recipe
        {
            Id = 4, Title = "Chicken Tikka Masala", Category = "main-courses",
            Ingredients = "Chicken thighs, yogurt, garam masala, tomato sauce, cream, onion, garlic, ginger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil the chicken until charred.\n3. Sauté onion, garlic, and ginger, then add tomato sauce and cream.\n4. Add chicken to the sauce and simmer 10 minutes.\n5. Serve with rice or naan.",
            AverageRating = 4.7, RatingCount = 18
        },
        new Recipe
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "desserts",
            Ingredients = "Dark chocolate, butter, eggs, sugar, flour",
            Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until thick.\n3. Fold chocolate mixture into eggs, then fold in flour.\n4. Pour into greased ramekins.\n5. Bake at 425°F for 12 minutes.\n6. Invert onto plates and serve immediately.",
            AverageRating = 4.9, RatingCount = 30
        },
        new Recipe
        {
            Id = 6, Title = "Tiramisu", Category = "desserts",
            Ingredients = "Ladyfingers, mascarpone, eggs, sugar, espresso, cocoa powder, marsala wine",
            Steps = "1. Whisk egg yolks with sugar, then fold in mascarpone.\n2. Whip egg whites and fold into mascarpone mixture.\n3. Dip ladyfingers in espresso mixed with marsala.\n4. Layer soaked ladyfingers and cream in a dish.\n5. Refrigerate overnight and dust with cocoa before serving.",
            AverageRating = 4.6, RatingCount = 15
        }
    };
}

